package io.github.tuanmanh28.learn.lesson02.exercises

// Shared types for the exercises — DO NOT edit this file.
//
// These are tiny FAKES of Android types so the tests run on the plain JVM (no emulator, no Robolectric).
// Only the part that matters for memory is modelled: who holds a reference to whom.

/** Fake of android.content.Context. A real Context gives access to resources, services, files… */
open class Context {
    /** Real Android: the process-wide Application object. It lives as long as the app → safe to keep forever. */
    open val applicationContext: Context get() = this
}

/** Fake of android.app.Application: exactly one per process, lives as long as the process. */
class Application(val name: String = "ReviewMobileApp") : Context()

/**
 * Fake of android.app.Activity: one screen. It is destroyed on back press, rotation, etc.
 * After [onDestroy] nothing long-lived may keep a reference to it, otherwise the whole screen
 * (views, bitmaps…) stays in memory = a memory leak.
 *
 * `open` so tests can create screens that also implement a listener interface.
 */
open class Activity(val name: String, private val app: Application) : Context() {
    override val applicationContext: Context get() = app

    /** Pretend this screen holds a big view tree / bitmap (~256 KB), so a leak is "expensive". */
    val viewTree = ByteArray(256 * 1024)

    /** What the screen has displayed (callbacks append here). */
    val shown = mutableListOf<String>()

    var isDestroyed = false
        private set

    fun onDestroy() {
        isDestroyed = true
    }

    override fun toString() = "Activity($name)"
}

/** Callbacks from an ad loader to the screen that requested the ad. */
interface AdLoadListener {
    fun onAdLoaded(unitId: String, ecpm: Double)
    fun onAdFailed(unitId: String, code: Int)
}

/**
 * A long-lived event bus (in a real app: a singleton inside the ad SDK, alive for the whole process).
 * Anything registered here stays reachable until it is unregistered.
 */
class AdEventBus {
    private val callbacks = LinkedHashMap<String, (String) -> Unit>()

    fun register(key: String, callback: (String) -> Unit) {
        callbacks[key] = callback
    }

    fun unregister(key: String) {
        callbacks.remove(key)
    }

    /** Sends [event] to every registered callback. */
    fun post(event: String) {
        callbacks.values.toList().forEach { it(event) }
    }

    val size: Int get() = callbacks.size
}

/** A decoded ad creative (banner image). Big → a good candidate for a cache that can be dropped under memory pressure. */
class AdCreative(val unitId: String, val bytes: ByteArray = ByteArray(64 * 1024))
